import { readFile, writeFile } from "node:fs/promises";

const root = new URL("..", import.meta.url);
const read = (name) => readFile(new URL(`server/${name}`, root), "utf8");
const [agents, helper, overlay, skills] = await Promise.all([
  read("agents.mjs"),
  read("agent-preset.mjs"),
  read("overlay.mjs"),
  read("skill-filesystem.mjs"),
]);
const source = [
  "// Generated by scripts/embed-overlay.mjs. Edit server/*.mjs and run npm run embed.",
  `export const AGENTS_MODULE = ${JSON.stringify(agents)};`,
  `export const AGENT_PRESET_MODULE = ${JSON.stringify(helper)};`,
  `export const OVERLAY_MODULE = ${JSON.stringify(overlay)};`,
  `export const SKILL_FILESYSTEM_MODULE = ${JSON.stringify(skills)};`,
  "",
].join("\n");
await writeFile(new URL("server/embedded-overlay.ts", root), source);
console.log("wrote server/embedded-overlay.ts");
